// Connect's route tree: file routes under src/routes, generated by the router plugin.
import type { AnyRoute } from "@tanstack/react-router";
// A project build with its own routes aliases this to its generated tree.
import type { FileRoutesById } from "@powerhousedao/connect/route-tree";
import { routeTree } from "@powerhousedao/connect/route-tree";
import type { ConnectRouteComponents } from "./route-components.js";

export { DRIVE_PENDING_MS } from "./route-components.js";
export type { ConnectRouteComponents } from "./route-components.js";

/** The home route's id; a tree change that moves it is a type error here. */
export const HOME_ROUTE_ID = "/_app/_content/" satisfies keyof FileRoutesById;
/** The sidebar layout's id; a project's _app/ routes nest in it. */
export const APP_ROUTE_ID = "/_app";
const CONTENT_ROUTE_ID = "/_app/_content";
const DRIVE_PATH = "/d/$driveSlug/{-$nodeSlug}";

type RouteOptions = { id?: string; path?: string };

// Generated routes carry their full id only once a router initialises them.
function findChild(parent: AnyRoute, idOrPath: string) {
  const children = (parent.children ?? []) as AnyRoute[];
  const child = children.find((route) => {
    const options = route.options as RouteOptions;
    return options.id === idOrPath || options.path === idOrPath;
  });
  if (!child) throw new Error(`Connect's route tree lacks ${idOrPath}`);
  return child;
}

// Named, so declarations reach the tree through the specifier a project aliases;
// inferred types would point at Connect's own generated file.
export type ConnectRootRoute = typeof routeTree;
export type ConnectRoutes = {
  routeTree: ConnectRootRoute;
  rootRoute: ConnectRootRoute;
  appRoute: FileRoutesById[typeof APP_ROUTE_ID];
  contentRoute: FileRoutesById[typeof CONTENT_ROUTE_ID];
  homeRoute: FileRoutesById[typeof HOME_ROUTE_ID];
  driveRoute: FileRoutesById[`${typeof CONTENT_ROUTE_ID}${typeof DRIVE_PATH}`];
};

/** Connect's routes in the generated tree; deployment routes attach to these. */
export function connectRoutes(): ConnectRoutes {
  const appRoute = findChild(routeTree, APP_ROUTE_ID);
  const contentRoute = findChild(appRoute, "/_content");
  return {
    routeTree,
    rootRoute: routeTree,
    appRoute: appRoute as ConnectRoutes["appRoute"],
    contentRoute: contentRoute as ConnectRoutes["contentRoute"],
    homeRoute: findChild(contentRoute, "/") as ConnectRoutes["homeRoute"],
    driveRoute: findChild(
      contentRoute,
      DRIVE_PATH,
    ) as ConnectRoutes["driveRoute"],
  };
}

/** Code routes, e.g. `createRoute({ getParentRoute: () => rootRoute })`, join
 * their parent's file routes; an embedding app without the router plugin adds routes so. */
export function addConnectRoutes(routes: readonly AnyRoute[]) {
  for (const route of routes) {
    const parent = route.options.getParentRoute() as AnyRoute | undefined;
    if (!parent) throw new Error("A Connect route needs getParentRoute");
    const children = (parent.children ?? []) as AnyRoute[];
    if (!children.includes(route)) parent.addChildren([...children, route]);
  }
}

/** The route tree; components reach its routes through router context. */
export function createConnectRouteTree(
  _components?: ConnectRouteComponents,
): ConnectRouteTree {
  const { homeRoute, driveRoute } = connectRoutes();
  return { routeTree, homeRoute, driveRoute };
}

export type ConnectRouteTree = Pick<
  ConnectRoutes,
  "routeTree" | "homeRoute" | "driveRoute"
>;
